using System.Runtime.InteropServices;
using System.Runtime.Intrinsics;

namespace ProdOp;

public static class MathOps
{
    /// <summary>Computes the product of all elements using SIMD vectorization.</summary>
    public static float Product(ReadOnlySpan<float> values)
    {
        if (values.IsEmpty) return 0f;

        ref float start = ref MemoryMarshal.GetReference(values);
        int length = values.Length;
        int i = 0;

        // Use 256-bit SIMD (8 floats) for the bulk of the work
        if (Vector256.IsHardwareAccelerated && length >= Vector256<float>.Count)
        {
            var acc = Vector256<float>.One;
            int lastBlockIndex = length - Vector256<float>.Count;
            for (; i <= lastBlockIndex; i += Vector256<float>.Count)
            {
                var vec = Vector256.LoadUnsafe(ref start, (nuint)i);
                acc *= vec;
            }

            // Reduce 8-wide accumulator to 4-wide, then to scalar
            var lo = acc.GetLower();
            var hi = acc.GetUpper();
            var combined = lo * hi;
            float product = combined[0] * combined[1] * combined[2] * combined[3];

            // Handle remaining elements
            for (; i < length; i++)
                product *= System.Runtime.CompilerServices.Unsafe.Add(ref start, i);

            return product;
        }

        if (Vector128.IsHardwareAccelerated && length >= Vector128<float>.Count)
        {
            var acc = Vector128<float>.One;
            int lastBlockIndex = length - Vector128<float>.Count;
            for (; i <= lastBlockIndex; i += Vector128<float>.Count)
            {
                var vec = Vector128.LoadUnsafe(ref start, (nuint)i);
                acc *= vec;
            }

            float product = acc[0] * acc[1] * acc[2] * acc[3];

            for (; i < length; i++)
                product *= System.Runtime.CompilerServices.Unsafe.Add(ref start, i);

            return product;
        }

        // Scalar fallback with 4x unrolling to hide multiply latency
        float p0 = 1f, p1 = 1f, p2 = 1f, p3 = 1f;
        int limit = length - 3;
        for (; i < limit; i += 4)
        {
            p0 *= System.Runtime.CompilerServices.Unsafe.Add(ref start, i);
            p1 *= System.Runtime.CompilerServices.Unsafe.Add(ref start, i + 1);
            p2 *= System.Runtime.CompilerServices.Unsafe.Add(ref start, i + 2);
            p3 *= System.Runtime.CompilerServices.Unsafe.Add(ref start, i + 3);
        }
        float result = p0 * p1 * p2 * p3;
        for (; i < length; i++)
            result *= System.Runtime.CompilerServices.Unsafe.Add(ref start, i);

        return result;
    }
}

